ALTER TABLE public.shelters ADD COLUMN location text NOT NULL DEFAULT '', ADD COLUMN contact_phone text NOT NULL DEFAULT '', ADD COLUMN adoption_heading text NOT NULL DEFAULT 'Adult cats looking for home', ADD COLUMN adoption_intro text NOT NULL DEFAULT 'Grown-up cats with settled personalities. Find your match and apply to adopt.', ADD COLUMN adoption_process text NOT NULL DEFAULT '';
GRANT UPDATE (name, location, contact_phone, adoption_heading, adoption_intro, adoption_process) ON public.shelters TO authenticated;
CREATE POLICY shelter_owner_update ON public.shelters FOR UPDATE TO authenticated USING (public.is_shelter_owner(id)) WITH CHECK (public.is_shelter_owner(id));
CREATE OR REPLACE FUNCTION public.public_adoption_page(_slug text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public AS $function$
SELECT jsonb_build_object('shelter',jsonb_build_object('id',s.id,'name',s.name,'slug',s.slug,'location',s.location,'contact_phone',s.contact_phone,'adoption_heading',s.adoption_heading,'adoption_intro',s.adoption_intro,'adoption_process',s.adoption_process),'cats',coalesce((SELECT jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'photo_url',c.photo_url,'breed',c.breed,'color',c.color,'age_years',c.age_years,'sex',c.sex,'temperament',c.temperament,'bio',c.bio,'tags',coalesce(c.tags,'{}')) ORDER BY c.created_at DESC) FROM public.cats c WHERE c.shelter_id=s.id AND c.stage='available'),'[]'::jsonb)) FROM public.shelters s WHERE s.slug=_slug
$function$;
GRANT EXECUTE ON FUNCTION public.public_adoption_page(text) TO anon, authenticated, service_role;